<script setup lang="ts">
import { computed, watch, ref } from 'vue';
import { state as stateSource, mode, catalog } from '../workbench/store';
const state=stateSource;
import { route as routeSource, go } from '../workbench/navigation';
const route=routeSource;
import { sessions,loadSessions,loading,liveError,request } from '../workbench/live';
const counts=computed(()=>({objects:catalog().filter(o=>o.status==='published').length,domains:state.domains.length,materials:catalog().filter(o=>o.kind==='material').length}));
const status=ref<{configured:boolean;model:string;connected:boolean}>();const statusError=ref('');
async function loadStatus(){try{status.value=await request('/api/live/status');statusError.value='';}catch(e){statusError.value=e instanceof Error?e.message:'状态读取失败';}}
watch(()=>mode.value,v=>{if(v==='real')void loadSessions();},{immediate:true});watch(()=>route.page,p=>{if(p==='config')void loadStatus();},{immediate:true});
</script>
<template><div class="wb-page">
  <template v-if="route.page==='dashboard'"><header class="page-header"><div><h2>运行总览</h2><p class="page-desc">{{mode==='demo'?'模型目录与学习记录；以下数量按当前本地记录计算。':'本机六下数学真实会话；尚未绑定正式学生身份或评价模型。'}}</p></div><button v-if="mode==='real'" class="btn" :disabled="loading" @click="loadSessions">刷新记录</button></header>
    <p v-if="mode==='real'&&liveError" class="callout danger">{{liveError}}。指标暂不可用，不能按零处理。</p><div class="metric-grid"><button class="metric-card" @click="go('trace-list')"><span>{{mode==='demo'?'示例活动':'可读取真实会话'}}</span><strong>{{mode==='demo'?state.activities.length:liveError?'—':sessions.length}}</strong><small>查看具体记录 →</small></button><button v-if="mode==='demo'" class="metric-card" @click="go('domain')"><span>领域</span><strong>{{counts.domains}}</strong><small>查看领域目录 →</small></button><button v-if="mode==='demo'" class="metric-card" @click="go('textbooks')"><span>教材</span><strong>{{counts.materials}}</strong><small>查看教材与章节 →</small></button><button class="metric-card" @click="go(mode==='demo'?'objects':'trace-list',{filter:mode==='real'?'error':''})"><span>{{mode==='demo'?'已保存示例定义':'有错误记录的会话'}}</span><strong>{{mode==='demo'?counts.objects:liveError?'—':sessions.filter(s=>s.error).length}}</strong><small>{{mode==='demo'?'不包含个人能力记录 →':'不等同于教学判断错误率 →'}}</small></button></div>
    <div class="two-columns"><section class="panel"><h3>最近修改</h3><div v-for="c in mode==='demo'?state.changes.slice(0,5):[]" :key="c.ref" class="list-row"><button class="text-link" @click="go('object',{id:c.ref})">{{c.note}} · {{c.ref}}</button><small>{{c.at}}</small></div><p v-if="mode==='real'||!state.changes.length" class="empty">尚无本次直接编辑产生的修改记录。</p></section><section class="panel"><h3>管理员工作入口</h3><div class="task-links"><button v-if="mode==='demo'" class="task-link" @click="go('textbooks',{id:'CH-001'})"><strong>准备一个章节</strong><span>内容、映射和目标在各自页面保存</span></button><button class="task-link" @click="go('trace-list')"><strong>核对一次学习判断</strong><span>查看活动事实及解释依据，记录意见</span></button><button v-if="mode==='demo'" class="task-link" @click="go('domain')"><strong>管理领域模型</strong><span>进入领域，添加或修改定义</span></button></div></section></div>
    <section class="panel"><h3>统计边界</h3><p>{{mode==='demo'?'示例目录只有已列出的对象和活动，不再展示虚构的全站学生规模、KC 掌握分布或总掌握率。':'列表来自本地会话文件；没有正式账号、课堂人数、模型准确率或学习效果统计。未记录的成本和性能指标不显示为零。'}}</p></section></template>
  <template v-else-if="route.page==='users'"><header class="page-header"><div><h2>用户管理</h2><p class="page-desc">学生、家长、管理员角色分开；本轮仅核对示例身份与学习空间的关系。</p></div></header><p class="callout">正式建档、亲子关系维护和账号找回仍属于 M11，本轮未接入。此列表不代表真实登录或服务端权限。</p><section class="table-card"><table class="data-table"><thead><tr><th>标识</th><th>名称</th><th>角色</th><th>关联</th></tr></thead><tbody><tr v-for="s in [...new Map(state.spaces.map(s=>[s.studentId,s])).values()]" :key="s.studentId"><td>{{s.studentId}}</td><td>{{s.studentName}}</td><td>学生</td><td><button class="text-link" @click="go('students',{id:s.studentId})">查看学习空间和状态</button></td></tr><tr><td>ADMIN-LOCAL</td><td>本地管理员（示例）</td><td>管理员</td><td>可直接编辑定义；系统记录修改版本</td></tr></tbody></table></section><p class="muted">迁入家长端的旧六上示例身份未映射到上述示例学生；不自动合并。</p></template>
  <template v-else-if="route.page==='config'"><header class="page-header"><div><h2>系统配置</h2><p class="page-desc">当前本地服务的只读状态。</p></div><button class="btn" @click="loadStatus">刷新</button></header><section class="panel"><p v-if="statusError" class="callout danger">{{statusError}}</p><dl v-if="status" class="field-list"><dt>模型</dt><dd>{{status.model}}</dd><dt>配置</dt><dd>{{status.configured?'已配置模型凭据（不在界面显示）':'尚未配置模型凭据'}}</dd><dt>真实课程范围</dt><dd>六年级下册数学；不使用示例能力状态</dd><dt>正式评价与模型维护服务</dt><dd>尚未接入；本轮定义编辑保存在浏览器</dd></dl><p class="callout">只读查阅不会调用模型。模型凭据继续由已有本地配置管理。</p></section></template>
</div></template>
